using System;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using BeamScheduleFormatter;
class SteelSectionRefreshUiTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var d in All(c))yield return d;}}static T Get<T>(object o,string key){return (T)o.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 [STAThread]static void Main(){Application.EnableVisualStyles();AccessCodes.Granted=true;foreach(Form form in new Form[]{new PurlinDesignForm(),new TrussConnectionForm()})using(form){form.Show();Application.DoEvents();var preview=All(form).OfType<SteelSectionPreview>().Single();var section=Get<ComboBox>(form,form is PurlinDesignForm?"profiles":"profile");int paints=0;preview.Invalidated+=(s,e)=>paints++;string original=preview.CurrentProfile.Name;section.SelectedIndex=(section.SelectedIndex+1)%section.Items.Count;Application.DoEvents();Check(paints>0,"Selection invalidates section preview: "+form.Text);Check(preview.CurrentProfile.Name==section.Text&&preview.CurrentProfile.Name!=original,"Section geometry follows chosen profile immediately: "+form.Text);if(form is TrussConnectionForm){var family=Get<ComboBox>(form,"family");family.SelectedItem="Double angle";Application.DoEvents();Check(paints>1,"Double-angle family selection refreshes assembly");}form.Close();}Console.WriteLine("PASS: "+checks+" native purlin/truss live section refresh checks");}
}
